const assetsList = `-- name: AssetsList :many
SELECT a.id, a.project_id, a.issue_id, a.uploaded_by, a.kind, a.filename, a.description, a.mime_type, a.byte_size, a.checksum, a.staging_key, a.staging_generation, a.published_key, a.published_generation, a.state, a.in_panel, a.uploaded_at, a.expires_at, a.published_at,u.display_name,i.revision AS issue_revision FROM attachments a JOIN users u ON u.id=a.uploaded_by JOIN issues i ON i.id=a.issue_id
WHERE a.issue_id=$1::uuid AND ((a.state='published' AND a.in_panel) OR ($2::boolean AND a.state='draft' AND a.uploaded_by=$3::uuid AND a.expires_at>now()))
AND (NOT $4::boolean OR (a.uploaded_at,a.id)>($5::timestamptz,$6::uuid))
ORDER BY a.uploaded_at,a.id LIMIT $7::integer
`

type AssetsListParams struct {
	IssueID          uuid.UUID          `json:"issue_id"`
	IncludeOwnDrafts bool               `json:"include_own_drafts"`
	CallerID         uuid.UUID          `json:"caller_id"`
	HasCursor        bool               `json:"has_cursor"`
	AfterTime        pgtype.Timestamptz `json:"after_time"`
	AfterID          uuid.UUID          `json:"after_id"`
	PageSize         int32              `json:"page_size"`
}

type AssetsListRow struct {
	ID                  uuid.UUID          `json:"id"`
	ProjectID           uuid.UUID          `json:"project_id"`
	IssueID             uuid.UUID          `json:"issue_id"`
	UploadedBy          uuid.UUID          `json:"uploaded_by"`
	Kind                string             `json:"kind"`
	Filename            string             `json:"filename"`
	Description         string             `json:"description"`
	MimeType            string             `json:"mime_type"`
	ByteSize            int64              `json:"byte_size"`
	Checksum            string             `json:"checksum"`
	StagingKey          string             `json:"staging_key"`
	StagingGeneration   int64              `json:"staging_generation"`
	PublishedKey        *string            `json:"published_key"`
	PublishedGeneration *int64             `json:"published_generation"`
	State               string             `json:"state"`
	InPanel             bool               `json:"in_panel"`
	UploadedAt          pgtype.Timestamptz `json:"uploaded_at"`
	ExpiresAt           pgtype.Timestamptz `json:"expires_at"`
	PublishedAt         pgtype.Timestamptz `json:"published_at"`
	DisplayName         string             `json:"display_name"`
	IssueRevision       int64              `json:"issue_revision"`
}

func (q *Queries) AssetsList(ctx context.Context, arg AssetsListParams) ([]AssetsListRow, error) {
	rows, err := q.db.Query(ctx, assetsList,
		arg.IssueID,
		arg.IncludeOwnDrafts,
		arg.CallerID,
		arg.HasCursor,
		arg.AfterTime,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AssetsListRow{}
	for rows.Next() {
		var i AssetsListRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.IssueID,
			&i.UploadedBy,
			&i.Kind,
			&i.Filename,
			&i.Description,
			&i.MimeType,
			&i.ByteSize,
			&i.Checksum,
			&i.StagingKey,
			&i.StagingGeneration,
			&i.PublishedKey,
			&i.PublishedGeneration,
			&i.State,
			&i.InPanel,
			&i.UploadedAt,
			&i.ExpiresAt,
			&i.PublishedAt,
			&i.DisplayName,
			&i.IssueRevision,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

